//! A shelf of colors: the module's main object, and a collection keyed by an enum.

// Generated by `dagger generate`; regenerate after changing exported items.
pub mod dagger_generated;

/// A color. Its members keep their default names, and callers name them as the engine
/// spells them, `RED` and `BLUE`.
#[dagger_sdk::enum_type]
pub enum Color {
    /// Red.
    Red,
    /// Blue.
    Blue,
}

/// The colors on the shelf. Its members have their default names, so they need no
/// markers.
#[dagger_sdk::object(root, collection, rename = "Shelf")]
pub struct Shelf {
    #[dagger(field)]
    keys: Vec<Color>,
    #[dagger(field)]
    delta: Option<dagger_sdk::CollectionDelta>,
    base: dagger_sdk::CollectionBase,
}

#[dagger_sdk::methods]
impl Shelf {
    #[dagger(constructor, rename = "shelf")]
    pub fn new() -> Shelf {
        Shelf {
            keys: vec![Color::Red, Color::Blue],
            delta: None,
            base: dagger_sdk::CollectionBase::default(),
        }
    }

    /// Returns the item of a color.
    #[dagger(function)]
    pub fn get(&self, color: Color) -> Item {
        let name = match color {
            Color::Red => "red",
            Color::Blue => "blue",
        };
        Item {
            name: name.to_owned(),
        }
    }

    /// Counts the colors this value holds.
    #[dagger(function)]
    pub fn count(&self) -> i64 {
        i64::try_from(self.keys.len()).unwrap_or(i64::MAX)
    }

    /// Returns the colors removed since the base.
    #[dagger(function)]
    pub async fn removed(&self) -> Result<Vec<String>, dagger_sdk::ModuleError> {
        let delta = self
            .delta
            .as_ref()
            .ok_or_else(|| dagger_sdk::ModuleError::new("the engine gave the shelf no delta"))?;
        Ok(delta.removed_keys().await?)
    }
}

/// One item on the shelf.
#[dagger_sdk::object]
pub struct Item {
    /// The item's color, in lower case.
    #[dagger(field)]
    name: String,
}
